                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("View the outputs of this specific group's tasks"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Show the logs of all groups' tasks"))
                .arg(Arg::new("json").short('j').long("json").action(ArgAction::SetTrue).help("Print the resulting tasks and output as json").long_help("Print the resulting tasks and output as json.\n\nBy default only the last lines will be returned unless --full is provided. Take care, as\nthe json cannot be streamed! If your logs are really huge, using --full can use all of\nyour machine's RAM."))
                .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of each task's output").long_help("Only print the last X lines of each task's output.\n\nThis is done by default if you're looking at multiple tasks."))
                .arg(Arg::new("full").short('f').long("full").action(ArgAction::SetTrue).help("Show the whole output"))
