        .subcommand(
            Command::new("follow")
                .about("Follow the output of a currently running task. This command works like \"tail -f\"")
                .arg(Arg::new("TASK_ID").value_name("TASK_ID").help("The id of the task you want to watch").long_help("The id of the task you want to watch.\n\nIf no or multiple tasks are running, you have to specify the id. If only a single task is\nrunning, you can omit the id."))
                .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of the output before following"))
        )
        .subcommand(
            Command::new("wait")
                .about("Wait until tasks are finished")
                .long_about("Wait until tasks are finished.\n\nBy default, this will wait for all tasks in the default group to finish.\n\nNote: This will also wait for all tasks that aren't somehow 'Done'. Includes: [Paused, Stashed,\nLocked, Queued, ...]")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("This allows you to wait for specific tasks to finish"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Wait for all tasks in a specific group"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Wait for all tasks across all groups and the default group"))
