                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m91\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
