                .arg(Arg::new("failed-in-group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP").help("Like `--all-failed`, but only restart tasks failed tasks of a specific group"))
                .arg(Arg::new("immediate").short('k').long("immediate").action(ArgAction::SetTrue).help("Immediately start the tasks, no matter how many open slots there are. This will ignore any\ndependencies tasks may have"))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue).help("Set the restarted task to a \"Stashed\" state. Useful to avoid immediate execution"))
