        .subcommand(
            Command::new("pause")
                .about("Either pause running tasks or specific groups of tasks")
                .long_about("Either pause running tasks or specific groups of tasks.\n\nBy default, pauses the default group and all its tasks. A paused queue (group) won't start any new\ntasks.")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("Pause these specific tasks"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Pause a specific group"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Pause all groups!"))
                .arg(Arg::new("wait").short('w').long("wait").action(ArgAction::SetTrue).help("Pause the specified groups, but let already running tasks finish by themselves"))
        )
        .subcommand(
            Command::new("kill")
                .about("Kill specific running tasks or whole task groups")
                .long_about("Kill specific running tasks or whole task groups.\n\nKills all tasks of the default group when no ids or a specific group are provided.")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("Kill these specific tasks"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Kill all running tasks in a group. This also pauses the group"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Kill all running tasks across ALL groups. This also pauses all groups"))
                .arg(Arg::new("signal").short('s').long("signal").value_name("SIGNAL").help("Send a UNIX signal instead of simply killing the process").long_help("Send a UNIX signal instead of simply killing the process.\n\nDISCLAIMER: This bypasses Pueue's process handling logic! You might enter weird invalid\nstates, use at your own descretion.\n\nThis argument also excepts the integer representation as well as the signal short name.\nE.g. `sigint`, `int`, or `2` are the same."))
        )
        .subcommand(
            Command::new("send")
                .about("Send something to a task. Useful for sending confirmations such as 'y\\n'")
