                .arg(Arg::new("INPUT").value_name("INPUT").required(true).help("The input that should be sent to the process"))
        )
        .subcommand(
            Command::new("edit")
                .about("Adjust editable properties of a task")
                .long_about("Adjust editable properties of a task.\n\nOnly stashed or queued tasks can be edited. A temporary folder folder/file will be opened by your\n$EDITOR to edit the tasks.")
