                        .arg(Arg::new("VALUE").value_name("VALUE").required(true).help("The value of the environment variable to set"))
                )
                .subcommand(
                    Command::new("unset")
                        .about("Remove a specific variable from a task's environment")
                        .arg(Arg::new("TASK_ID").value_name("TASK_ID").required(true).help("The id of the task for which the variable should be set"))
                        .arg(Arg::new("KEY").value_name("KEY").required(true).help("The name of the environment variable to set"))
                )
        )
        .subcommand(
            Command::new("group")
                .about("Use this to add or remove groups")
                .long_about("Use this to add or remove groups.\n\nBy default, this will simply display all known groups.")
                .arg(Arg::new("json").short('j').long("json").action(ArgAction::SetTrue).help("Print the list of groups as json"))
                .subcommand(
                    Command::new("add")
                        .about("Add a group by name")
                        .arg(Arg::new("NAME").value_name("NAME").required(true))
                        .arg(Arg::new("parallel").short('p').long("parallel").value_name("PARALLEL").help("Set the amount of parallel tasks this group can have").long_help("Set the amount of parallel tasks this group can have.\n\nSetting this to 0 means an unlimited amount of parallel tasks."))
                )
                .subcommand(
                    Command::new("remove")
                        .about("Remove a group by name. This will move all tasks in this group to the default group!")
                        .arg(Arg::new("NAME").value_name("NAME").required(true))
                )
        )
        .subcommand(
            Command::new("status")
                .about("Display the current status of all tasks")
                .long_about("Display the current status of all tasks\n\nUsers can specify a custom query to filter for specific values, order by a column\nor limit the amount of tasks listed.\n\nSyntax:\n   [column_selection]? [filter]* [order_by]? [limit]?\n\nwhere:\n  - column_selection := `columns=[column]([column],)*`\n  - column := `id | status | command | label | path | enqueue_at | dependencies | start |\n  end`\n  - filter := `[filter_column] [filter_op] [filter_value]`\n    (note: not all columns support all operators, see \"Filter columns\" below.)\n  - filter_column := `status | command | label | start | end | enqueue_at`\n  - filter_op := `= | != | < | > | %=`\n    (`%=` means 'contains', as in the test value is a substring of the column value)\n  - order_by := `order_by [column] [order_direction]`\n  - order_direction := `asc | desc`\n  - limit := `[limit_type]? [limit_count]`\n  - limit_type := `first | last`\n  - limit_count := a positive integer\n\nFilter columns:\n  - `status` supports the operators `=`, `!=`\n    against test values that are:\n      - strings like `queued`, `stashed`, `paused`, `running`, `success`, `failed`\n  - `command`, `label` support the operators `=`, `!=`, `%=`\n    against test values that are:\n      - strings like `some text`\n  - `start`, `end`, `enqueue_at` contain a datetime\n    which support the operators `=`, `!=`, `<`, `>`\n    against test values that are:\n      - date like `YYYY-MM-DD`\n      - time like `HH:mm:ss` or `HH:mm`\n      - datetime like `YYYY-MM-DDHH:mm:ss`\n        (note there is currently no separator between the date and the time)\n\nExamples:\n  - `status=running`\n  - `command%=echo`\n  - `label=mytask`\n  - `columns=id,status,command status=running start > 2023-05-2112:03:17 order_by command\n  first 5`\n\nThe formal syntax is defined here:\nhttps://github.com/Nukesor/pueue/blob/main/pueue/src/client/commands/state/query/syntax.pest\n\nMore documentation is on the query syntax PR:\nhttps://github.com/Nukesor/pueue/issues/350#issue-1359083118")
                .arg(Arg::new("QUERY").value_name("QUERY").num_args(1..).help("Users can specify a custom query to filter for specific values, order by a column or\nlimit the amount of tasks listed. Use `--help` for the full syntax definition"))
                .arg(Arg::new("json").short('j').long("json").action(ArgAction::SetTrue).help("Print the current state as json to stdout. This does not include the output of tasks. Use\n`log -j` if you want everything"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Only show tasks of a specific group"))
        )
        .subcommand(
            Command::new("log")
                .about("Display the log output of finished tasks")
                .long_about("Display the log output of finished tasks.\n\nOnly the last few lines will be shown by default. If you want to follow the output of a task, please\nuse the \"follow\" subcommand.")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("View the task output of these specific tasks"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("View the outputs of this specific group's tasks"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Show the logs of all groups' tasks"))
                .arg(Arg::new("json").short('j').long("json").action(ArgAction::SetTrue).help("Print the resulting tasks and output as json").long_help("Print the resulting tasks and output as json.\n\nBy default only the last lines will be returned unless --full is provided. Take care, as\nthe json cannot be streamed! If your logs are really huge, using --full can use all of\nyour machine's RAM."))
                .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of each task's output").long_help("Only print the last X lines of each task's output.\n\nThis is done by default if you're looking at multiple tasks."))
                .arg(Arg::new("full").short('f').long("full").action(ArgAction::SetTrue).help("Show the whole output"))
        )
        .subcommand(
            Command::new("follow")
                .about("Follow the output of a currently running task. This command works like \"tail -f\"")
                .arg(Arg::new("TASK_ID").value_name("TASK_ID").help("The id of the task you want to watch").long_help("The id of the task you want to watch.\n\nIf no or multiple tasks are running, you have to specify the id. If only a single task is\nrunning, you can omit the id."))
                .arg(Arg::new("lines").short('l').long("lines").value_name("LINES").help("Only print the last X lines of the output before following"))
        )
        .subcommand(
            Command::new("wait")
                .about("Wait until tasks are finished")
                .long_about("Wait until tasks are finished.\n\nBy default, this will wait for all tasks in the default group to finish.\n\nNote: This will also wait for all tasks that aren't somehow 'Done'. Includes: [Paused, Stashed,\nLocked, Queued, ...]")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("This allows you to wait for specific tasks to finish"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Wait for all tasks in a specific group"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Wait for all tasks across all groups and the default group"))
                .arg(Arg::new("quiet").short('q').long("quiet").action(ArgAction::SetTrue).help("Don't show any log output while waiting"))
                .arg(Arg::new("status").short('s').long("status").value_name("STATUS").help("Wait for tasks to reach a specific task status"))
        )
        .subcommand(
            Command::new("clean")
                .about("Remove all finished tasks from the list")
                .arg(Arg::new("successful-only").short('s').long("successful-only").action(ArgAction::SetTrue).help("Only clean tasks that finished successfully"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Only clean tasks of a specific group"))
        )
        .subcommand(
            Command::new("reset")
                .about("Kill all tasks, clean up afterwards and reset EVERYTHING!")
                .arg(Arg::new("groups").short('g').long("groups").value_name("GROUPS").help("If groups are specified, only those specific groups will be reset"))
                .arg(Arg::new("force").short('f').long("force").action(ArgAction::SetTrue).help("Don't ask for any confirmation"))
        )
        .subcommand(
            Command::new("shutdown")
                .about("Remotely shut down the daemon. Should only be used if the daemon isn't started by a\nservice manager")
        )
        .subcommand(
            Command::new("parallel")
                .about("Set the amount of allowed parallel tasks")
                .long_about("Set the amount of allowed parallel tasks\n\nBy default, adjusts the amount of the default group.\n\nNo tasks will be stopped, if this is lowered. This limit is only considered when tasks are\nscheduled.")
                .arg(Arg::new("PARALLEL_TASKS").value_name("PARALLEL_TASKS").help("The amount of allowed parallel tasks").long_help("The amount of allowed parallel tasks.\n\nSetting this to 0 means an unlimited amount of parallel tasks."))
                .arg(Arg::new("group").short('g').long("group").value_name("group").help("Set the amount for a specific group"))
        )
        .subcommand(
            Command::new("completions")
                .about("Generates shell completion files")
