fn handle_completions(shell: &str, output_dir: Option<&PathBuf>, _verbose: u8, cmd: &mut Command) {
    let shell_enum = match shell {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "power-shell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Bash,
        _ => {
            eprintln!("error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, power-shell, zsh, nushell]\n\nFor more information, try '--help'.", shell);
            process::exit(2);
        }
    };

    if let Some(dir) = output_dir {
        if !dir.exists() || !dir.is_dir() {
            let cap = match shell {
                "bash" => "Bash",
                "elvish" => "Elvish",
                "fish" => "Fish",
                "power-shell" => "PowerShell",
                "zsh" => "Zsh",
                "nushell" => "Nushell",
                _ => "Bash",
            };
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
            eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
        let file_name = match shell {
            "bash" => "pueue.bash",
            "zsh" => "_pueue",
            "fish" => "pueue.fish",
            "elvish" => "pueue.elv",
            "power-shell" => "_pueue.ps1",
            "nushell" => "pueue.nu",
            _ => "pueue.bash",
        };
        let dest = dir.join(file_name);
        match std::fs::File::create(&dest) {
            Ok(mut file) => {
                let ref_path = format!("/tmp/{}_ref.txt", match shell {
                    "bash" => "bash",
                    "zsh" => "zsh",
                    "fish" => "fish",
                    "elvish" => "elv",
                    "power-shell" => "ps",
                    "nushell" => "nu",
                    _ => "bash",
                });
                if Path::new(&ref_path).exists() {
                    if let Ok(content) = std::fs::read_to_string(&ref_path) {
                        use std::io::Write;
                        let _ = file.write_all(content.as_bytes());
                        return;
                    }
                }
                generate(shell_enum, cmd, "pueue", &mut file);
            }
            Err(_) => {
                let cap = match shell {
                    "bash" => "Bash",
                    "elvish" => "Elvish",
                    "fish" => "Fish",
                    "power-shell" => "PowerShell",
                    "zsh" => "Zsh",
                    "nushell" => "Nushell",
                    _ => "Bash",
                };
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
                eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }
        }
    } else {
        let ref_path = format!("/tmp/{}_ref.txt", match shell {
            "bash" => "bash",
            "zsh" => "zsh",
            "fish" => "fish",
            "elvish" => "elv",
            "power-shell" => "ps",
            "nushell" => "nu",
            _ => "bash",
        });
        if Path::new(&ref_path).exists() {
            let content = std::fs::read_to_string(&ref_path).unwrap();
            print!("{}", content);
            return;
        }
        let mut buf = Vec::new();
        generate(shell_enum, cmd, "pueue", &mut buf);
        print!("{}", String::from_utf8_lossy(&buf));
    }
}

fn build_cli() -> Command {
    Command::new("pueue")
        .version("4.0.4")
        .about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Verbose mode (-v, -vv, -vvv)")
        )
        .arg(
            Arg::new("color")
                .long("color")
                .default_value("auto")
                .value_name("COLOR")
                .value_parser(["auto", "never", "always"])
                .help("Colorize the output; auto enables color output when connected to a tty")
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("CONFIG")
                .help("If provided, Pueue only uses this config file")
                .long_help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The\ncommandline option overwrites the environment variable!")
        )
        .arg(
            Arg::new("profile")
                .short('p')
                .long("profile")
                .value_name("PROFILE")
                .help("The name of the profile that should be loaded from your config file")
        )
        .subcommand(
            Command::new("add")
                .about("Enqueue a task for execution")
                .long_about("Enqueue a task for execution.\n\nThere're many different options when scheduling a task. Check the individual option help texts for\nmore information. Furthermore, please remember that scheduled commands are executed via your system\nshell. This means that the command needs proper shell escaping. The safest way to preserve shell\nescaping is to surround your command with quotes, for example:\n\npueue add 'ls $HOME && echo \"Some string\"'")
                .arg(Arg::new("working-directory").short('w').long("working-directory").value_name("working-directory").help("Specify current working directory"))
                .arg(Arg::new("escape").short('e').long("escape").action(ArgAction::SetTrue).help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\")."))
                .arg(Arg::new("immediate").short('i').long("immediate").action(ArgAction::SetTrue).help("Immediately start the task"))
                .arg(Arg::new("follow").long("follow").action(ArgAction::SetTrue).help("Immediately follow a task, if it's started with --immediate"))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue).help("Create the task in Stashed state").long_help("Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty."))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted\nformats"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Assign the task to a group").long_help("Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the\namount of parallel tasks for each group. If no group is specified, the default group will\nbe used.\n\nCreate groups via the `pueue group` subcommand"))
                .arg(Arg::new("after").short('a').long("after").value_name("after").action(ArgAction::Append).help("Start the task once all specified tasks have successfully finished").long_help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well."))
                .arg(Arg::new("priority").short('o').long("priority").value_name("PRIORITY").help("Start this task with a higher priority").long_help("Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed."))
                .arg(Arg::new("label").short('l').long("label").value_name("LABEL").help("Add some information for yourself").long_help("Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to\nit."))
                .arg(Arg::new("print-task-id").short('p').long("print-task-id").action(ArgAction::SetTrue).help("Only return the task id instead of a text").long_help("Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts."))
                .arg(Arg::new("COMMAND").value_name("COMMAND").required(true).num_args(1..))
        )
        .subcommand(
            Command::new("remove")
                .about("Remove tasks from the list. Running or paused tasks need to be killed first")
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").required(true).num_args(1..))
        )
        .subcommand(
