                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..).help("Start these specific tasks. Paused tasks will resumed. Queued/Stashed tasks will be\nforce-started"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Resume a specific group and all paused tasks in it").long_help("Resume a specific group and all paused tasks in it.\n\nThe group will be set to running and its paused tasks will be resumed."))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Resume all groups!").long_help("Resume all groups!\n\nAll groups will be set to running and paused tasks will be resumed."))
