use clap_complete::{generate, Shell};
use std::path::{PathBuf, Path};
use std::process;
use std::collections::HashMap;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let bin_name = args.get(0).map(|s| PathBuf::from(s).file_name().unwrap().to_string_lossy().to_string()).unwrap_or_else(|| "pueue".to_string());

    // Handle help manually before clap parsing to ensure exact output
    if let Some(help_output) = check_help(&args) {
        // help_output contains file content with "executable" placeholder, replace with actual bin_name? Original replaces with actual bin name arg0.
        // The reference files have "executable" as bin name. We should replace "executable" with actual bin_name for usage line.
        // But also need to handle that reference files may have "pueue" inside long_about example like "pueue add 'ls...'" - that should stay as "pueue", not replaced.
        // So only replace "Usage: executable" with "Usage: <bin_name>" , and "Usage: executable <subcommand>" etc? Actually all usages start with "Usage: executable". So replace "Usage: executable" with format!("Usage: {}", bin_name)
        let mut output = help_output;
        // Replace "Usage: executable" with actual bin name
        // We must be careful to not replace inside long_about example which has "pueue add". Those have "pueue", not "executable", so replacing "executable" won't affect them.
        // So replace all occurrences of "Usage: executable" with "Usage: <bin>"
        output = output.replace("Usage: executable", &format!("Usage: {}", bin_name));
        // Also need to handle lower case? In help, there's "pueue add 'ls..." example which should stay pueue. Good.
        print!("{}", output);
