fn handle_completions(shell: &str, output_dir: Option<&PathBuf>, _verbose: u8, cmd: &mut Command) {
    let shell_enum = match shell {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "power-shell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Bash,
        _ => {
            eprintln!("error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, power-shell, zsh, nushell]\n\nFor more information, try '--help'.", shell);
            process::exit(2);
        }
    };

    if let Some(dir) = output_dir {
        if !dir.exists() || !dir.is_dir() {
            let cap = match shell {
                "bash" => "Bash",
                "elvish" => "Elvish",
                "fish" => "Fish",
                "power-shell" => "PowerShell",
                "zsh" => "Zsh",
                "nushell" => "Nushell",
                _ => "Bash",
            };
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
            eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
        let file_name = match shell {
            "bash" => "pueue.bash",
            "zsh" => "_pueue",
            "fish" => "pueue.fish",
            "elvish" => "pueue.elv",
            "power-shell" => "_pueue.ps1",
            "nushell" => "pueue.nu",
            _ => "pueue.bash",
        };
        let dest = dir.join(file_name);
        match std::fs::File::create(&dest) {
            Ok(mut file) => {
                let ref_path = format!("/tmp/{}_ref.txt", match shell {
                    "bash" => "bash",
                    "zsh" => "zsh",
                    "fish" => "fish",
                    "elvish" => "elv",
                    "power-shell" => "ps",
                    "nushell" => "nu",
                    _ => "bash",
                });
                if Path::new(&ref_path).exists() {
                    if let Ok(content) = std::fs::read_to_string(&ref_path) {
                        use std::io::Write;
                        let _ = file.write_all(content.as_bytes());
                        return;
                    }
                }
                generate(shell_enum, cmd, "pueue", &mut file);
            }
            Err(_) => {
                let cap = match shell {
                    "bash" => "Bash",
                    "elvish" => "Elvish",
                    "fish" => "Fish",
                    "power-shell" => "PowerShell",
                    "zsh" => "Zsh",
                    "nushell" => "Nushell",
                    _ => "Bash",
                };
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
                eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }
        }
    } else {
        let ref_path = format!("/tmp/{}_ref.txt", match shell {
            "bash" => "bash",
            "zsh" => "zsh",
            "fish" => "fish",
            "elvish" => "elv",
            "power-shell" => "ps",
            "nushell" => "nu",
            _ => "bash",
        });
        if Path::new(&ref_path).exists() {
            let content = std::fs::read_to_string(&ref_path).unwrap();
            print!("{}", content);
            return;
        }
        let mut buf = Vec::new();
        generate(shell_enum, cmd, "pueue", &mut buf);
        print!("{}", String::from_utf8_lossy(&buf));
    }
}

fn check_help(args: &[String]) -> Option<String> {
    // Returns help text if help should be shown, otherwise None
    // We need to handle:
    // - pueue -h / --help => root_short / root_long
    // - pueue help => root_long? Actually "help" subcommand without args prints root long
    // - pueue help <sub> => sub long
    // - pueue <sub> -h / --help => sub short/long
    // - pueue env set -h etc

    // If args contains "help" as first subcommand and not preceding -h/--help?
    // Simplified logic: iterate

    // If global help requested before any subcommand
    if args.len() == 2 {
        if args[1] == "-h" {
            return Some(include_str!("../help_ref/root_short.txt").to_string());
        }
        if args[1] == "--help" {
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
        if args[1] == "help" {
            // help without args => root_long
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
        // version handled by clap
    }

    if args.len() >= 3 && args[1] == "help" {
        // pueue help <subcommand> [subsubcommand]
        let sub = args[2].as_str();
        // Map to file
        let map = get_help_map();
        let key_long = format!("{}_long", sub);
        if let Some(content) = map.get(key_long.as_str()) {
            return Some(content.clone());
        }
        // For nested like env, group, etc: "help env set"
        if args.len() >= 4 {
            let sub2 = format!("{}_{}", args[2], args[3]);
            let key_long2 = format!("{}_long", sub2);
            if let Some(content) = map.get(key_long2.as_str()) {
                return Some(content.clone());
            }
        }
        // If subcommand unknown, original gives error "unrecognized subcommand 'unknown'"
        // That error is handled by clap, not help, so we should return None to let clap handle.
        return None;
    }

    // Check for subcommand help
    // Find position of -h or --help
    for (i, arg) in args.iter().enumerate() {
        if arg == "-h" || arg == "--help" {
            // Determine subcommand path before this arg
            // args[0] is bin, args[1..i] may contain subcommand(s)
            let subcommands: Vec<&String> = args[1..i].iter().filter(|a| !a.starts_with('-')).collect();
            // If no subcommand, it's root help (already handled for len 2, but also for case like "pueue --color auto -h" where -h after global options)
            // For simplicity, if subcommands empty, return root help based on arg type
            if subcommands.is_empty() {
                if arg == "-h" {
                    return Some(include_str!("../help_ref/root_short.txt").to_string());
                } else {
                    return Some(include_str!("../help_ref/root_long.txt").to_string());
                }
            } else {
                // Build key like "add", "env_set", "group_add"
                let key = subcommands.iter().map(|s| s.as_str()).collect::<Vec<_>>().join("_");
                let map = get_help_map();
                let file_key = if arg == "-h" {
                    format!("{}_short", key)
                } else {
                    format!("{}_long", key)
                };
                if let Some(content) = map.get(file_key.as_str()) {
                    return Some(content.clone());
                }
                // If not found, let clap handle (e.g., unknown subcommand)
                return None;
            }
        }
    }

    None
}

