fn build_cli() -> Command {
    Command::new("pueue")
        .version("4.0.4")
        .about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Verbose mode (-v, -vv, -vvv)")
        )
        .arg(
            Arg::new("color")
                .long("color")
                .default_value("auto")
                .value_name("COLOR")
                .value_parser(["auto", "never", "always"])
                .help("Colorize the output; auto enables color output when connected to a tty")
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("CONFIG")
                .help("If provided, Pueue only uses this config file")
                .long_help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The\ncommandline option overwrites the environment variable!")
        )
        .arg(
            Arg::new("profile")
                .short('p')
                .long("profile")
                .value_name("PROFILE")
                .help("The name of the profile that should be loaded from your config file")
        )
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .action(ArgAction::SetTrue)
                .help("Print help (see more with '--help')")
        )
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .action(ArgAction::SetTrue)
                .help("Print version")
        )
        .subcommand(
            Command::new("add")
                .about("Enqueue a task for execution")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("working-directory").short('w').long("working-directory").value_name("working-directory").help("Specify current working directory"))
                .arg(Arg::new("escape").short('e').long("escape").action(ArgAction::SetTrue).help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\")."))
                .arg(Arg::new("immediate").short('i').long("immediate").action(ArgAction::SetTrue).help("Immediately start the task"))
                .arg(Arg::new("follow").long("follow").action(ArgAction::SetTrue).help("Immediately follow a task, if it's started with --immediate"))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue).help("Create the task in Stashed state"))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay").help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted\nformats"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Assign the task to a group"))
                .arg(Arg::new("after").short('a').long("after").value_name("after").num_args(1..).action(ArgAction::Append).help("Start the task once all specified tasks have successfully finished"))
                .arg(Arg::new("priority").short('o').long("priority").value_name("PRIORITY").help("Start this task with a higher priority"))
                .arg(Arg::new("label").short('l').long("label").value_name("LABEL").help("Add some information for yourself"))
                .arg(Arg::new("print-task-id").short('p').long("print-task-id").action(ArgAction::SetTrue).help("Only return the task id instead of a text"))
                .arg(Arg::new("COMMAND").value_name("COMMAND").required(true).num_args(1..))
        )
        .subcommand(
            Command::new("remove")
                .about("Remove tasks from the list. Running or paused tasks need to be killed first")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").required(true).num_args(1..))
        )
        .subcommand(
            Command::new("switch")
                .about("Switches the queue position of two commands")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_ID_1").value_name("TASK_ID_1").required(true))
                .arg(Arg::new("TASK_ID_2").value_name("TASK_ID_2").required(true))
        )
        .subcommand(
            Command::new("stash")
                .about("Stash a task. Stashed tasks won't be automatically started")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay"))
        )
        .subcommand(
            Command::new("enqueue")
                .about("Enqueue stashed tasks. They'll be handled normally afterwards")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay"))
        )
        .subcommand(
            Command::new("start")
                .about("Resume operation of specific tasks or groups of tasks")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
        )
        .subcommand(
            Command::new("restart")
                .about("Restart failed or successful task(s)")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("all-failed").short('a').long("all-failed").action(ArgAction::SetTrue))
                .arg(Arg::new("failed-in-group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP"))
                .arg(Arg::new("immediate").short('k').long("immediate").action(ArgAction::SetTrue))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue))
                .arg(Arg::new("in-place").short('i').long("in-place").action(ArgAction::SetTrue))
                .arg(Arg::new("not-in-place").long("not-in-place").action(ArgAction::SetTrue))
                .arg(Arg::new("edit").short('e').long("edit").action(ArgAction::SetTrue))
        )
        .subcommand(
            Command::new("pause")
                .about("Either pause running tasks or specific groups of tasks")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
                .arg(Arg::new("wait").short('w').long("wait").action(ArgAction::SetTrue))
        )
        .subcommand(
            Command::new("kill")
                .about("Kill specific running tasks or whole task groups")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help (see more with '--help')"))
                .arg(Arg::new("TASK_IDS").value_name("TASK_IDS").num_args(1..))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
                .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
                .arg(Arg::new("signal").short('s').long("signal").value_name("SIGNAL"))
        )
        .subcommand(
            Command::new("send")
                .about("Send something to a task. Useful for sending confirmations such as 'y\\n'")
