fn build_cli() -> Command {
    Command::new("pueue")
        .version("4.0.4")
        .about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .disable_help_subcommand(true)
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Verbose mode (-v, -vv, -vvv)")
        )
        .arg(
            Arg::new("color")
                .long("color")
                .default_value("auto")
                .value_name("COLOR")
                .value_parser(["auto", "never", "always"])
                .help("Colorize the output; auto enables color output when connected to a tty")
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("CONFIG")
                .help("If provided, Pueue only uses this config file")
                .long_help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The\ncommandline option overwrites the environment variable!")
        )
        .arg(
            Arg::new("profile")
                .short('p')
                .long("profile")
                .value_name("PROFILE")
                .help("The name of the profile that should be loaded from your config file")
        )
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .action(ArgAction::SetTrue)
                .help("Print help (see more with '--help')")
        )
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .action(ArgAction::SetTrue)
                .help("Print version")
        )
        .subcommand(
            Command::new("add")
                .about("Enqueue a task for execution")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                .arg(Arg::new("working-directory").short('w').long("working-directory").value_name("working-directory"))
                .arg(Arg::new("escape").short('e').long("escape").action(ArgAction::SetTrue))
                .arg(Arg::new("immediate").short('i').long("immediate").action(ArgAction::SetTrue))
                .arg(Arg::new("follow").long("follow").action(ArgAction::SetTrue))
                .arg(Arg::new("stashed").short('s').long("stashed").action(ArgAction::SetTrue))
                .arg(Arg::new("delay").short('d').long("delay").value_name("delay"))
                .arg(Arg::new("group").short('g').long("group").value_name("GROUP"))
