}
fn log_info(msg: &str) {
    let ts = timestamp();
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m {}", ts, msg);
}
fn log_info_path(prefix: &str, p: &PathBuf) {
    let ts = timestamp();
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m {} \"{}\"", ts, prefix, p.display());
