    let effective_config_path: Option<PathBuf> = if let Some(p) = config_path_opt.clone() {
        Some(p)
    } else if let Some(p) = config_path_from_env.clone() {
        Some(p)
    } else {
        None
    };

    if verbose >= 1 {
        log_info("Parsing config files");
    }

    let mut config_content: Option<String> = None;

