        match std::fs::read_to_string(&p) {
            Ok(content) => {
                config_content = Some(content);
            }
            Err(_) => {
                print_config_open_error(&p);
                process::exit(1);
            }
        }
    } else {
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        let default1 = home.join(".config/pueue/pueue.yml");
        let default2 = PathBuf::from("./pueue.yml");
        if verbose >= 1 {
            log_info_path("Checking path:", &default1);
            log_info_path("Checking path:", &default2);
        }
        if default1.exists() {
            if verbose >= 1 {
                log_info_path("Found config file at:", &default1);
            }
            config_content = Some(std::fs::read_to_string(&default1).unwrap_or_default());
        } else if default2.exists() {
            if verbose >= 1 {
                log_info_path("Found config file at:", &default2);
            }
            config_content = Some(std::fs::read_to_string(&default2).unwrap_or_default());
        } else {
            if verbose >= 1 {
                log_info("No config file found. Use default config.");
            }
            eprintln!("Error: ");
