fn handle_completions(shell: &str, output_dir: Option<&PathBuf>, _verbose: u8, _cmd: &mut Command) {
    const BASH: &str = include_str!("../completion_ref/bash.txt");
    const ZSH: &str = include_str!("../completion_ref/zsh.txt");
    const FISH: &str = include_str!("../completion_ref/fish.txt");
    const ELVISH: &str = include_str!("../completion_ref/elvish.txt");
    const POWERSHELL: &str = include_str!("../completion_ref/powershell.txt");
    const NUSHELL: &str = include_str!("../completion_ref/nushell.txt");

    if let Some(dir) = output_dir {
        if !dir.exists() || !dir.is_dir() {
            let cap = match shell {
                "bash" => "Bash",
                "elvish" => "Elvish",
                "fish" => "Fish",
                "power-shell" => "PowerShell",
                "zsh" => "Zsh",
                "nushell" => "Nushell",
                _ => "Bash",
            };
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
            eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
        let file_name = match shell {
            "bash" => "pueue.bash",
            "zsh" => "_pueue",
            "fish" => "pueue.fish",
            "elvish" => "pueue.elv",
            "power-shell" => "_pueue.ps1",
            "nushell" => "pueue.nu",
            _ => "pueue.bash",
        };
        let dest = dir.join(file_name);
        match std::fs::File::create(&dest) {
            Ok(mut file) => {
                use std::io::Write;
                let content = match shell {
                    "bash" => BASH,
                    "zsh" => ZSH,
                    "fish" => FISH,
                    "elvish" => ELVISH,
                    "power-shell" => POWERSHELL,
                    "nushell" => NUSHELL,
                    _ => BASH,
                };
                let _ = file.write_all(content.as_bytes());
            }
            Err(_) => {
                let cap = match shell {
                    "bash" => "Bash",
                    "elvish" => "Elvish",
                    "fish" => "Fish",
                    "power-shell" => "PowerShell",
                    "zsh" => "Zsh",
                    "nushell" => "Nushell",
                    _ => "Bash",
                };
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
                eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }
        }
    } else {
        let content = match shell {
            "bash" => BASH,
            "zsh" => ZSH,
            "fish" => FISH,
            "elvish" => ELVISH,
            "power-shell" => POWERSHELL,
            "nushell" => NUSHELL,
            _ => BASH,
        };
        print!("{}", content);
    }
}

fn check_help(args: &[String]) -> Option<String> {
    if args.len() == 2 {
        if args[1] == "-h" {
            return Some(include_str!("../help_ref/root_short.txt").to_string());
        }
        if args[1] == "--help" {
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
        if args[1] == "help" {
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
    }

    if args.len() >= 3 && args[1] == "help" {
        let sub = args[2].as_str();
        let map = get_help_map();
        let key_long = format!("{}_long", sub);
        if let Some(content) = map.get(key_long.as_str()) {
            return Some(content.clone());
        }
        if args.len() >= 4 {
            let sub2 = format!("{}_{}", args[2], args[3]);
            let key_long2 = format!("{}_long", sub2);
            if let Some(content) = map.get(key_long2.as_str()) {
                return Some(content.clone());
            }
        }
        return None;
    }

    for (i, arg) in args.iter().enumerate() {
        if arg == "-h" || arg == "--help" {
            let subcommands: Vec<&String> = args[1..i].iter().filter(|a| !a.starts_with('-')).collect();
            if subcommands.is_empty() {
                if arg == "-h" {
                    return Some(include_str!("../help_ref/root_short.txt").to_string());
                } else {
                    return Some(include_str!("../help_ref/root_long.txt").to_string());
                }
            } else {
                let key = subcommands.iter().map(|s| s.as_str()).collect::<Vec<_>>().join("_");
                let map = get_help_map();
                let file_key = if arg == "-h" {
                    format!("{}_short", key)
                } else {
                    format!("{}_long", key)
                };
                if let Some(content) = map.get(file_key.as_str()) {
                    return Some(content.clone());
                }
                return None;
            }
        }
    }

    None
}

