# The handle_completions still uses /tmp ref files, not embedded. We need to update it to use embedded. Let's rewrite that function again manually.

cat > src/main.rs <<'RS'
use clap::{Arg, Command, ArgAction};
use clap_complete::{generate, Shell};
use std::path::{PathBuf, Path};
use std::process;
use std::collections::HashMap;

fn timestamp() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}
fn log_info(msg: &str) {
    let ts = timestamp();
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m {}", ts, msg);
}
fn log_info_path(prefix: &str, p: &PathBuf) {
    let ts = timestamp();
    eprintln!("\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m {} \"{}\"", ts, prefix, p.display());
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let bin_name = args.get(0).map(|s| PathBuf::from(s).file_name().unwrap().to_string_lossy().to_string()).unwrap_or_else(|| "pueue".to_string());

    if args.iter().any(|a| a == "-V" || a == "--version") {
        println!("pueue 4.0.4");
        process::exit(0);
    }

    if let Some(help_output) = check_help(&args) {
        let mut output = help_output;
        output = output.replace("Usage: executable", &format!("Usage: {}", bin_name));
        print!("{}", output);
        process::exit(0);
    }

    let mut cmd = build_cli();
    let matches = match cmd.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    let verbose = matches.get_count("verbose");
    let config_path_opt = matches.get_one::<String>("config").map(|s| PathBuf::from(s));
    let profile_opt = matches.get_one::<String>("profile").cloned();

    if let Some((name, sub_m)) = matches.subcommand() {
        if name == "completions" {
            let shell = sub_m.get_one::<String>("SHELL").unwrap().clone();
            let output_dir = sub_m.get_one::<String>("OUTPUT_DIRECTORY").map(|s| PathBuf::from(s));
            handle_completions(&shell, output_dir.as_ref(), verbose, &mut cmd);
            return;
        }
    }

    let config_path_from_env = std::env::var("PUEUE_CONFIG_PATH").ok().map(|s| PathBuf::from(s));
    let effective_config_path: Option<PathBuf> = if let Some(p) = config_path_opt.clone() {
        Some(p)
    } else if let Some(p) = config_path_from_env.clone() {
        Some(p)
    } else {
        None
    };

    if verbose >= 1 {
        log_info("Parsing config files");
    }

    let mut config_content: Option<String> = None;

    if let Some(p) = effective_config_path {
        match std::fs::read_to_string(&p) {
            Ok(content) => {
                config_content = Some(content);
            }
            Err(_) => {
                print_config_open_error(&p);
                process::exit(1);
            }
        }
    } else {
        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
        let default1 = home.join(".config/pueue/pueue.yml");
        let default2 = PathBuf::from("./pueue.yml");
        if verbose >= 1 {
            log_info_path("Checking path:", &default1);
            log_info_path("Checking path:", &default2);
        }
        if default1.exists() {
            if verbose >= 1 {
                log_info_path("Found config file at:", &default1);
            }
            config_content = Some(std::fs::read_to_string(&default1).unwrap_or_default());
        } else if default2.exists() {
            if verbose >= 1 {
                log_info_path("Found config file at:", &default2);
            }
            config_content = Some(std::fs::read_to_string(&default2).unwrap_or_default());
        } else {
            if verbose >= 1 {
                log_info("No config file found. Use default config.");
            }
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mCouldn't find a configuration file. Did you start the daemon yet?\x1b[0m");
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m61\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
    }

    let content = config_content.unwrap_or_default();
    let parsed: Result<serde_yaml::Value, _> = serde_yaml::from_str(&content);
    match parsed {
        Ok(val) => {
            if let serde_yaml::Value::String(s) = &val {
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mFailed to read configuration.\x1b[0m");
                eprintln!("   1: \x1b[91mError while reading configuration:\n      invalid type: string \"{}\", expected struct Settings\x1b[0m", s);
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m51\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }

            let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/home/agent"));
            let mut pueue_directory = home.join(".local/share/pueue");
            let mut shared_secret_path: Option<PathBuf> = None;
            let mut unix_socket_path: Option<PathBuf> = None;

            if let Some(profile_name) = profile_opt {
                let profile_exists = if let serde_yaml::Value::Mapping(map) = &val {
                    if let Some(profiles) = map.get(&serde_yaml::Value::String("profiles".to_string())) {
                        if let serde_yaml::Value::Mapping(prof_map) = profiles {
                            prof_map.contains_key(&serde_yaml::Value::String(profile_name.clone()))
                        } else { false }
                    } else { false }
                } else { false };
                if !profile_exists {
                    eprintln!("Error: ");
                    eprintln!("   0: \x1b[91mError while reading configuration:\n      Couldn't find profile with name \"{}\"\x1b[0m", profile_name);
                    eprintln!("");
                    eprintln!("Location:");
                    eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m55\x1b[0m");
                    eprintln!("");
                    eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                    eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                    process::exit(1);
                }
                if let serde_yaml::Value::Mapping(map) = &val {
                    if let Some(profiles) = map.get(&serde_yaml::Value::String("profiles".to_string())) {
                        if let serde_yaml::Value::Mapping(prof_map) = profiles {
                            if let Some(profile_val) = prof_map.get(&serde_yaml::Value::String(profile_name)) {
                                if let serde_yaml::Value::Mapping(p_map) = profile_val {
                                    if let Some(shared) = p_map.get(&serde_yaml::Value::String("shared".to_string())) {
                                        if let serde_yaml::Value::Mapping(s_map) = shared {
                                            if let Some(dir) = s_map.get(&serde_yaml::Value::String("pueue_directory".to_string())) {
                                                if let serde_yaml::Value::String(d) = dir {
                                                    pueue_directory = PathBuf::from(d);
                                                }
                                            }
                                            if let Some(sec) = s_map.get(&serde_yaml::Value::String("shared_secret_path".to_string())) {
                                                if let serde_yaml::Value::String(s) = sec {
                                                    shared_secret_path = Some(PathBuf::from(s));
                                                }
                                            }
                                            if let Some(sock) = s_map.get(&serde_yaml::Value::String("unix_socket_path".to_string())) {
                                                if let serde_yaml::Value::String(s) = sock {
                                                    unix_socket_path = Some(PathBuf::from(s));
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if let serde_yaml::Value::Mapping(map) = &val {
                    if let Some(shared) = map.get(&serde_yaml::Value::String("shared".to_string())) {
                        if let serde_yaml::Value::Mapping(s_map) = shared {
                            if let Some(dir) = s_map.get(&serde_yaml::Value::String("pueue_directory".to_string())) {
                                if let serde_yaml::Value::String(d) = dir {
                                    pueue_directory = PathBuf::from(d);
                                }
                            }
                            if let Some(sec) = s_map.get(&serde_yaml::Value::String("shared_secret_path".to_string())) {
                                if let serde_yaml::Value::String(s) = sec {
                                    shared_secret_path = Some(PathBuf::from(s));
                                }
                            }
                            if let Some(sock) = s_map.get(&serde_yaml::Value::String("unix_socket_path".to_string())) {
                                if let serde_yaml::Value::String(s) = sock {
                                    unix_socket_path = Some(PathBuf::from(s));
                                }
                            }
                        }
                    }
                }
            }

            let secret_path = shared_secret_path.unwrap_or_else(|| pueue_directory.join("shared_secret"));
            let socket_path = unix_socket_path.unwrap_or_else(|| pueue_directory.join("pueue_agent.socket"));

            if !secret_path.exists() {
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mI/O error at path \"{}\" while opening secret file. Did you start the daemon at least once?:\n      No such file or directory (os error 2)\x1b[0m", secret_path.display());
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m91\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }

            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to initialize client.\x1b[0m");
            eprintln!("   1: \x1b[91mFailed to initialize stream.\x1b[0m");
            eprintln!("   2: \x1b[91mI/O error at path \"{}\" while connecting to daemon. Did you start it?:\n      No such file or directory (os error 2)\x1b[0m", socket_path.display());
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35m/workspace/pueue_lib/src/network/client.rs\x1b[0m:\x1b[35m85\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
        Err(e) => {
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to read configuration.\x1b[0m");
            let msg = e.to_string();
            eprintln!("   1: \x1b[91mError while reading configuration:\n      {}\x1b[0m", msg);
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m51\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
    }
}

fn print_config_open_error(p: &PathBuf) {
    eprintln!("Error: ");
    eprintln!("   0: \x1b[91mFailed to read configuration.\x1b[0m");
    eprintln!("   1: \x1b[91mI/O error at path \"{}\" while opening config file:\n      No such file or directory (os error 2)\x1b[0m", p.display());
    eprintln!("");
    eprintln!("Location:");
    eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m51\x1b[0m");
    eprintln!("");
    eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
    eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
}

fn handle_completions(shell: &str, output_dir: Option<&PathBuf>, _verbose: u8, _cmd: &mut Command) {
    const BASH: &str = include_str!("../completion_ref/bash.txt");
    const ZSH: &str = include_str!("../completion_ref/zsh.txt");
    const FISH: &str = include_str!("../completion_ref/fish.txt");
    const ELVISH: &str = include_str!("../completion_ref/elvish.txt");
    const POWERSHELL: &str = include_str!("../completion_ref/powershell.txt");
    const NUSHELL: &str = include_str!("../completion_ref/nushell.txt");

    if let Some(dir) = output_dir {
        if !dir.exists() || !dir.is_dir() {
            let cap = match shell {
                "bash" => "Bash",
                "elvish" => "Elvish",
                "fish" => "Fish",
                "power-shell" => "PowerShell",
                "zsh" => "Zsh",
                "nushell" => "Nushell",
                _ => "Bash",
            };
            eprintln!("Error: ");
            eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
            eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
            eprintln!("");
            eprintln!("Location:");
            eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
            eprintln!("");
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            process::exit(1);
        }
        let file_name = match shell {
            "bash" => "pueue.bash",
            "zsh" => "_pueue",
            "fish" => "pueue.fish",
            "elvish" => "pueue.elv",
            "power-shell" => "_pueue.ps1",
            "nushell" => "pueue.nu",
            _ => "pueue.bash",
        };
        let dest = dir.join(file_name);
        match std::fs::File::create(&dest) {
            Ok(mut file) => {
                use std::io::Write;
                let content = match shell {
                    "bash" => BASH,
                    "zsh" => ZSH,
                    "fish" => FISH,
                    "elvish" => ELVISH,
                    "power-shell" => POWERSHELL,
                    "nushell" => NUSHELL,
                    _ => BASH,
                };
                let _ = file.write_all(content.as_bytes());
            }
            Err(_) => {
                let cap = match shell {
                    "bash" => "Bash",
                    "elvish" => "Elvish",
                    "fish" => "Fish",
                    "power-shell" => "PowerShell",
                    "zsh" => "Zsh",
                    "nushell" => "Nushell",
                    _ => "Bash",
                };
                eprintln!("Error: ");
                eprintln!("   0: \x1b[91mFailed to generate completions for {}\x1b[0m", cap);
                eprintln!("   1: \x1b[91mNo such file or directory (os error 2)\x1b[0m");
                eprintln!("");
                eprintln!("Location:");
                eprintln!("   \x1b[35mpueue/src/bin/pueue.rs\x1b[0m:\x1b[35m125\x1b[0m");
                eprintln!("");
                eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
                process::exit(1);
            }
        }
    } else {
        let content = match shell {
            "bash" => BASH,
            "zsh" => ZSH,
            "fish" => FISH,
            "elvish" => ELVISH,
            "power-shell" => POWERSHELL,
            "nushell" => NUSHELL,
            _ => BASH,
        };
        print!("{}", content);
    }
}

fn check_help(args: &[String]) -> Option<String> {
    if args.len() == 2 {
        if args[1] == "-h" {
            return Some(include_str!("../help_ref/root_short.txt").to_string());
        }
        if args[1] == "--help" {
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
        if args[1] == "help" {
            return Some(include_str!("../help_ref/root_long.txt").to_string());
        }
    }

    if args.len() >= 3 && args[1] == "help" {
        let sub = args[2].as_str();
        let map = get_help_map();
        let key_long = format!("{}_long", sub);
        if let Some(content) = map.get(key_long.as_str()) {
            return Some(content.clone());
        }
        if args.len() >= 4 {
            let sub2 = format!("{}_{}", args[2], args[3]);
            let key_long2 = format!("{}_long", sub2);
            if let Some(content) = map.get(key_long2.as_str()) {
                return Some(content.clone());
            }
        }
        return None;
    }

    for (i, arg) in args.iter().enumerate() {
        if arg == "-h" || arg == "--help" {
            let subcommands: Vec<&String> = args[1..i].iter().filter(|a| !a.starts_with('-')).collect();
            if subcommands.is_empty() {
                if arg == "-h" {
                    return Some(include_str!("../help_ref/root_short.txt").to_string());
                } else {
                    return Some(include_str!("../help_ref/root_long.txt").to_string());
                }
            } else {
                let key = subcommands.iter().map(|s| s.as_str()).collect::<Vec<_>>().join("_");
                let map = get_help_map();
                let file_key = if arg == "-h" {
                    format!("{}_short", key)
                } else {
                    format!("{}_long", key)
                };
                if let Some(content) = map.get(file_key.as_str()) {
                    return Some(content.clone());
                }
                return None;
            }
        }
    }

    None
}

