                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
        )
        .subcommand(
            Command::new("parallel")
                .about("Set the amount of allowed parallel tasks")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                .arg(Arg::new("PARALLEL_TASKS").value_name("PARALLEL_TASKS"))
                .arg(Arg::new("group").short('g').long("group").value_name("group"))
        )
        .subcommand(
            Command::new("completions")
                .about("Generates shell completion files")
                .disable_help_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                .arg(Arg::new("SHELL").value_name("SHELL").required(true).value_parser(["bash", "elvish", "fish", "power-shell", "zsh", "nushell"]))
                .arg(Arg::new("OUTPUT_DIRECTORY").value_name("OUTPUT_DIRECTORY"))
        )
        .subcommand(
            Command::new("help")
                .about("Print this message or the help of the given subcommand(s)")
        )
}
